NAME_PREFIXES = ["Тёмный", "Сияющий", "Забытый", "Вечный", "Падший", "Бескрайний", "Тайный", "Кровавый", "Золотой", "Серебряный", "Стальной", "Нефритовый", "Багровый", "Ледяной", "Огненный", "Шёпотный", "Звёздный", "Лунный", "Кристальный", "Дымный"]

NAME_SUFFIXES = ["Хранитель", "Пепел", "Звёзд", "Теней", "Мечты", "Хаоса", "Света", "Бездны", "Вечности", "Рассвета", "Заката", "Пустоты", "Искры", "Кристалла", "Дракона", "Волка", "Орла", "Грозы", "Ветра", "Моря"]

def generate_world(genre: str, tag: str) -> str:
    world_desc = random.choice(WORLD_DESC_TEMPLATES)
    local_desc = random.choice(LOCAL_DESC_TEMPLATES)
    plot_start = random.choice(PLOT_START_TEMPLATES)
    name_template = random.choice(["{prefix} {suffix}", "{suffix} {genre}", "Земля {suffix}", "Мир {prefix}", "{genre} {suffix}"])
    
    prefix = random.choice(NAME_PREFIXES)
    suffix = random.choice(NAME_SUFFIXES)
    name = name_template.format(prefix=prefix, suffix=suffix, genre=genre)
    
    world_desc = world_desc.format(genre=genre, tag=tag)
    local_desc = local_desc.format(genre=genre, tag=tag)
    plot_start = plot_start.format(genre=genre, tag=tag)
    
    return f"Название: {name}\n\nОбщее описание мира:\n{world_desc}\n\nЛокальное описание:\n{local_desc}\n\nСюжетная вводная:\n{plot_start}"
